values
('dph-peh-extra-mcq-01','Pharmacy','Diploma in Pharmacy','mcq','free',1401,'{"question":"Which branch studies patterns of medicine use in populations?","translation":"जनसमुदायमा औषधि प्रयोगको ढाँचा अध्ययन गर्ने शाखा कुन हो?","options":["Pharmacoepidemiology","Anatomy","Pharmaceutics","Botany"],"correctIndex":0,"explanation":"Pharmacoepidemiology applies epidemiological methods to medicine use and effects.","explanationNe":"यसले औषधिको प्रयोग र प्रभावलाई जनसमुदायमा epidemiological विधिबाट अध्ययन गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-02','Pharmacy','Diploma in Pharmacy','mcq','free',1402,'{"question":"Which measure counts new cases over a defined period?","translation":"निश्चित अवधिमा देखिएका नयाँ घटना कुन मापनले जनाउँछ?","options":["Prevalence","Incidence","Mortality proportion","Case fatality only"],"correctIndex":1,"explanation":"Incidence measures new cases arising during a specified period.","explanationNe":"Incidence ले निश्चित अवधिमा देखिएका नयाँ घटना मापन गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-03','Pharmacy','Diploma in Pharmacy','mcq','free',1403,'{"question":"A point prevalence estimate refers to cases present:","translation":"Point prevalence ले कुन अवस्था जनाउँछ?","options":["At a specific point in time","Only in the future","Only new cases","Only deaths"],"correctIndex":0,"explanation":"Point prevalence counts all existing cases at a particular time.","explanationNe":"यसले निश्चित समयमा रहेका सबै घटना गन्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-04','Pharmacy','Diploma in Pharmacy','mcq','free',1404,'{"question":"A cohort study commonly begins by grouping people according to:","translation":"Cohort study मा मानिसलाई सामान्यतया कुन आधारमा समूह बनाइन्छ?","options":["Exposure status","Outcome only","Alphabetical order","Age alone in every study"],"correctIndex":0,"explanation":"Cohort studies compare groups defined by exposure and follow outcomes over time.","explanationNe":"यसमा exposure भएका र नभएका समूहलाई समयसँगै follow गरिन्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-05','Pharmacy','Diploma in Pharmacy','mcq','free',1405,'{"question":"A case-control study is especially useful for studying:","translation":"Case-control study कुन अवस्थामा उपयोगी हुन्छ?","options":["Rare diseases or outcomes","Only common exposures","Medicine prices","Stock balances"],"correctIndex":0,"explanation":"It starts with outcome status and looks back for prior exposures; it can be useful for rare outcomes.","explanationNe":"यसले रोग/नतिजा भएका र नभएका समूहबाट पहिलेको exposure तुलना गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-06','Pharmacy','Diploma in Pharmacy','mcq','free',1406,'{"question":"A cross-sectional study measures exposure and outcome:","translation":"Cross-sectional study ले exposure र outcome कहिले मापन गर्छ?","options":["At one point or short period","Only after ten years","Before birth only","Only in animals"],"correctIndex":0,"explanation":"It provides a snapshot of a population at a particular time or short period.","explanationNe":"यसले निश्चित समयमा जनसमुदायको अवस्था देखाउँछ।"}'::jsonb,true),
('dph-peh-extra-mcq-07','Pharmacy','Diploma in Pharmacy','mcq','free',1407,'{"question":"Random allocation is a defining feature of:","translation":"Random allocation कुन अध्ययनको विशेषता हो?","options":["Randomized controlled trial","Case report","Ecological description only","Cross-sectional survey only"],"correctIndex":0,"explanation":"Randomized controlled trials allocate interventions by chance.","explanationNe":"Randomized controlled trial मा intervention संयोगका आधारमा बाँडिन्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-08','Pharmacy','Diploma in Pharmacy','mcq','free',1408,'{"question":"A possible confounder is a factor associated with:","translation":"Confounder हुन सक्ने कारक कुनसँग सम्बन्धित हुन्छ?","options":["Exposure and outcome","Only study title","Only data entry format","Only medicine packaging"],"correctIndex":0,"explanation":"Confounding can distort an exposure-outcome association when a third factor is related to both.","explanationNe":"तेस्रो कारक exposure र outcome दुवैसँग सम्बन्धित हुँदा सम्बन्ध गलत देखिन सक्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-09','Pharmacy','Diploma in Pharmacy','mcq','free',1409,'{"question":"Recall bias is particularly relevant when participants are asked to remember:","translation":"Recall bias कुन अवस्थामा महत्त्वपूर्ण हुन्छ?","options":["Past exposures","Current room temperature only","Future events","Drug label colour"],"correctIndex":0,"explanation":"Recall bias occurs when groups remember or report past exposures differently.","explanationNe":"समूहहरूले विगतको exposure फरक तरिकाले सम्झँदा recall bias हुन्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-10','Pharmacy','Diploma in Pharmacy','mcq','free',1410,'{"question":"Which source is commonly used to identify a possible medicine safety signal?","translation":"औषधि सुरक्षा संकेत पहिचान गर्न कुन स्रोत प्रयोग हुन सक्छ?","options":["Adverse drug reaction reports","Only pharmacy decoration","Patient shoe size","Supplier logo"],"correctIndex":0,"explanation":"Spontaneous ADR reports can help generate safety signals, although they cannot alone prove causation.","explanationNe":"ADR रिपोर्टले सुरक्षा संकेत देखाउन सक्छ तर एक्लैले कारण प्रमाणित गर्दैन।"}'::jsonb,true),
('dph-peh-extra-mcq-11','Pharmacy','Diploma in Pharmacy','mcq','free',1411,'{"question":"An adverse drug reaction is best described as:","translation":"Adverse drug reaction भन्नाले के बुझिन्छ?","options":["A harmful and unintended response to a medicine at normal use","Any medicine advertisement","A medicine shortage","A packaging preference"],"correctIndex":0,"explanation":"An ADR is a harmful, unintended response associated with medicine use at normal doses.","explanationNe":"सामान्य प्रयोगमा औषधिसँग सम्बन्धित हानिकारक तथा अनिच्छित प्रतिक्रिया ADR हो।"}'::jsonb,true),
('dph-peh-extra-mcq-12','Pharmacy','Diploma in Pharmacy','mcq','free',1412,'{"question":"Pharmacovigilance primarily aims to:","translation":"Pharmacovigilance को मुख्य उद्देश्य के हो?","options":["Improve medicine safety","Increase medicine sales","Replace diagnosis","Stop all treatment"],"correctIndex":0,"explanation":"It detects, assesses, understands and helps prevent adverse effects and medicine-related problems.","explanationNe":"यसले औषधिका adverse effect पहिचान, मूल्याङ्कन र रोकथाममा सहयोग गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-13','Pharmacy','Diploma in Pharmacy','mcq','free',1413,'{"question":"Drug utilization review compares medicine use against:","translation":"Drug utilization review ले औषधि प्रयोगलाई केसँग तुलना गर्छ?","options":["Predefined standards or criteria","Patient clothing","Pharmacy opening hours","Weather forecasts"],"correctIndex":0,"explanation":"DUR assesses prescribing and use against agreed criteria.","explanationNe":"DUR ले औषधि प्रयोगलाई तोकिएका मापदण्डसँग तुलना गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-14','Pharmacy','Diploma in Pharmacy','mcq','free',1414,'{"question":"Which is a suitable indicator for reviewing antibiotic use?","translation":"Antibiotic प्रयोग मूल्याङ्कन गर्न कुन सूचक उपयोगी हुन्छ?","options":["Proportion of prescriptions containing an antibiotic","Number of pharmacy chairs","Colour of prescription paper","Number of windows"],"correctIndex":0,"explanation":"Antibiotic-prescribing indicators can help monitor patterns and support stewardship.","explanationNe":"Antibiotic भएको prescription को अनुपातले प्रयोगको ढाँचा अनुगमन गर्न सहयोग गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-15','Pharmacy','Diploma in Pharmacy','mcq','free',1415,'{"question":"Antimicrobial stewardship promotes:","translation":"Antimicrobial stewardship ले के प्रोत्साहन गर्छ?","options":["Appropriate antimicrobial selection and use","Antibiotics for every cold","Sharing leftover antibiotics","Unsupervised dose changes"],"correctIndex":0,"explanation":"Stewardship supports the right antimicrobial, dose, route and duration when indicated.","explanationNe":"आवश्यक अवस्थामा सही antimicrobial, dose, route र अवधि प्रयोग गर्न सहयोग गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-16','Pharmacy','Diploma in Pharmacy','mcq','free',1416,'{"question":"Which is an example of primary prevention?","translation":"Primary prevention को उदाहरण कुन हो?","options":["Vaccination","Rehabilitation after stroke","Screening for complications","Treatment of established disease"],"correctIndex":0,"explanation":"Primary prevention aims to prevent disease before it occurs.","explanationNe":"रोग हुनुअघि रोकथाम गर्नु primary prevention हो।"}'::jsonb,true),
('dph-peh-extra-mcq-17','Pharmacy','Diploma in Pharmacy','mcq','free',1417,'{"question":"Screening asymptomatic people for early disease is generally:","translation":"लक्षण नभएका व्यक्तिमा रोग चाँडै पत्ता लगाउने screening कुन prevention हो?","options":["Secondary prevention","Primary prevention","Tertiary prevention","Palliative care only"],"correctIndex":0,"explanation":"Secondary prevention focuses on early detection and prompt treatment.","explanationNe":"Secondary prevention ले रोग चाँडै पत्ता लगाएर उपचारमा जोड दिन्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-18','Pharmacy','Diploma in Pharmacy','mcq','free',1418,'{"question":"Rehabilitation to reduce disability is an example of:","translation":"अशक्तता घटाउन गरिने rehabilitation कुन prevention हो?","options":["Tertiary prevention","Primary prevention","Primordial prevention only","Screening"],"correctIndex":0,"explanation":"Tertiary prevention reduces complications, disability and impact of established disease.","explanationNe":"Tertiary prevention ले स्थापित रोगका जटिलता र अशक्तता घटाउँछ।"}'::jsonb,true),
('dph-peh-extra-mcq-19','Pharmacy','Diploma in Pharmacy','mcq','free',1419,'{"question":"Disease surveillance includes:","translation":"Disease surveillance मा के समावेश हुन्छ?","options":["Systematic collection and analysis of health data","Only treatment billing","Only medicine ordering","Only staff attendance"],"correctIndex":0,"explanation":"Surveillance collects, analyzes, interprets and shares health data for action.","explanationNe":"यसले जनस्वास्थ्य कार्यका लागि स्वास्थ्य तथ्यांक संकलन र विश्लेषण गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-20','Pharmacy','Diploma in Pharmacy','mcq','free',1420,'{"question":"A notifiable disease should be reported through:","translation":"Report गर्नुपर्ने रोग कहाँ रिपोर्ट गर्नुपर्छ?","options":["Approved public-health reporting channel","Personal social media only","No reporting system","Medicine supplier"],"correctIndex":0,"explanation":"Use the legally and institutionally approved reporting pathway.","explanationNe":"कानुन तथा संस्थाले स्वीकृत गरेको reporting channel प्रयोग गर्नुपर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-21','Pharmacy','Diploma in Pharmacy','mcq','free',1421,'{"question":"Which is a major environmental health determinant?","translation":"Environmental health को प्रमुख निर्धारक कुन हो?","options":["Safe drinking water","Phone brand","Exam timetable","Medicine logo"],"correctIndex":0,"explanation":"Safe water is a fundamental environmental health factor.","explanationNe":"सुरक्षित पिउने पानी वातावरणीय स्वास्थ्यको आधारभूत पक्ष हो।"}'::jsonb,true),
('dph-peh-extra-mcq-22','Pharmacy','Diploma in Pharmacy','mcq','free',1422,'{"question":"Contaminated drinking water can contribute to:","translation":"दूषित पिउने पानीले के गराउन सक्छ?","options":["Waterborne infections","Improved immunity in all cases","Medicine expiry","Better sanitation"],"correctIndex":0,"explanation":"Contaminated water can transmit infectious agents and cause waterborne disease.","explanationNe":"दूषित पानीले संक्रमण फैलाएर waterborne disease गराउन सक्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-23','Pharmacy','Diploma in Pharmacy','mcq','free',1423,'{"question":"Healthcare waste should be segregated:","translation":"स्वास्थ्यजन्य फोहोर कहिले/कहाँ छुट्याउनुपर्छ?","options":["At the point of generation","After mixing all waste","Only at the landfill","Once a month"],"correctIndex":0,"explanation":"Segregation at source improves safety and downstream handling.","explanationNe":"उत्पादन भएको स्थानमै छुट्याउँदा सुरक्षा र व्यवस्थापन राम्रो हुन्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-24','Pharmacy','Diploma in Pharmacy','mcq','free',1424,'{"question":"Sharps should be discarded into:","translation":"धारिला वस्तु कहाँ फाल्नुपर्छ?","options":["Puncture-resistant sharps container","Open plastic shopping bag","Food waste bin","Desk drawer"],"correctIndex":0,"explanation":"Puncture-resistant containers reduce needle-stick and sharps injuries.","explanationNe":"Puncture-resistant container ले सुई/धारिलो वस्तुबाट हुने चोट घटाउँछ।"}'::jsonb,true),
('dph-peh-extra-mcq-25','Pharmacy','Diploma in Pharmacy','mcq','free',1425,'{"question":"Which practice reduces healthcare-associated infection risk?","translation":"स्वास्थ्य संस्थामा संक्रमणको जोखिम घटाउने अभ्यास कुन हो?","options":["Hand hygiene","Reusing disposable needles","Mixing clean and contaminated items","Skipping cleaning"],"correctIndex":0,"explanation":"Hand hygiene is a core infection-prevention measure.","explanationNe":"हातको स्वच्छता संक्रमण रोकथामको मुख्य उपाय हो।"}'::jsonb,true),
('dph-peh-extra-mcq-26','Pharmacy','Diploma in Pharmacy','mcq','free',1426,'{"question":"Which is an example of a social determinant of health?","translation":"स्वास्थ्यको सामाजिक निर्धारकको उदाहरण कुन हो?","options":["Education and income","Tablet colour","Medicine brand","Hospital wall paint"],"correctIndex":0,"explanation":"Education and income can influence access to care and health outcomes.","explanationNe":"शिक्षा र आम्दानीले स्वास्थ्य सेवा पहुँच र स्वास्थ्य नतिजामा असर गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-27','Pharmacy','Diploma in Pharmacy','mcq','free',1427,'{"question":"A risk factor is:","translation":"Risk factor भन्नाले के बुझिन्छ?","options":["A characteristic associated with increased chance of an outcome","A guaranteed cause in every person","A medicine label","A type of stock card"],"correctIndex":0,"explanation":"A risk factor is associated with a higher probability of an outcome but may not guarantee it.","explanationNe":"Risk factor ले outcome को सम्भावना बढाउन सक्छ तर निश्चित कारण नै हुन्छ भन्ने होइन।"}'::jsonb,true),
('dph-peh-extra-mcq-28','Pharmacy','Diploma in Pharmacy','mcq','free',1428,'{"question":"Relative risk compares:","translation":"Relative risk ले के तुलना गर्छ?","options":["Risk in exposed group with risk in unexposed group","Two medicine prices only","Two expiry dates","Two hospital wards by size"],"correctIndex":0,"explanation":"Relative risk is the ratio of outcome risk in exposed versus unexposed groups.","explanationNe":"यसले exposure भएको र नभएको समूहको जोखिम अनुपात तुलना गर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-29','Pharmacy','Diploma in Pharmacy','mcq','free',1429,'{"question":"An odds ratio is commonly reported in:","translation":"Odds ratio सामान्यतया कुन अध्ययनमा प्रयोग हुन्छ?","options":["Case-control studies","Only laboratory experiments","Stock audits","Drug dispensing labels"],"correctIndex":0,"explanation":"Odds ratios are commonly used to quantify exposure-outcome association in case-control studies.","explanationNe":"Case-control study मा exposure र outcome बीचको सम्बन्ध जनाउन odds ratio प्रयोग हुन्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-30','Pharmacy','Diploma in Pharmacy','mcq','free',1430,'{"question":"A confidence interval expresses:","translation":"Confidence interval ले के जनाउँछ?","options":["Uncertainty around an estimate","The medicine expiry date","A guaranteed range of individual outcomes","The sample name"],"correctIndex":0,"explanation":"A confidence interval gives a range of values compatible with the data under the method used.","explanationNe":"यसले तथ्यांकअनुसार अनुमान वरिपरिको अनिश्चितताको दायरा देखाउँछ।"}'::jsonb,true),
('dph-peh-extra-mcq-31','Pharmacy','Diploma in Pharmacy','mcq','free',1431,'{"question":"A p-value should be interpreted with:","translation":"p-value लाई केसँगै बुझ्नुपर्छ?","options":["Effect size, confidence interval and study context","Only whether it is below 0.05","Medicine colour","Sample label"],"correctIndex":0,"explanation":"Statistical significance alone does not establish clinical importance or causation.","explanationNe":"Statistical significance मात्रले clinical महत्त्व वा कारण प्रमाणित गर्दैन।"}'::jsonb,true),
('dph-peh-extra-mcq-32','Pharmacy','Diploma in Pharmacy','mcq','free',1432,'{"question":"Which is a limitation of spontaneous ADR reporting?","translation":"स्वेच्छिक ADR reporting को सीमा कुन हो?","options":["Under-reporting may occur","It captures every reaction","It always proves causation","It replaces clinical assessment"],"correctIndex":0,"explanation":"Many suspected reactions may not be reported, and reports alone do not prove causality.","explanationNe":"धेरै ADR रिपोर्ट नहुन सक्छन् र रिपोर्ट मात्रले कारण प्रमाणित गर्दैन।"}'::jsonb,true),
('dph-peh-extra-mcq-33','Pharmacy','Diploma in Pharmacy','mcq','free',1433,'{"question":"A medicine safety signal means:","translation":"Medicine safety signal भन्नाले के बुझिन्छ?","options":["Information suggesting a possible new or changed safety issue","Final proof in every case","A marketing slogan","A stock reorder level"],"correctIndex":0,"explanation":"A signal warrants further assessment; it is not automatically proof of causation.","explanationNe":"Safety signal थप मूल्याङ्कन गर्नुपर्ने सूचना हो, स्वतः कारणको प्रमाण होइन।"}'::jsonb,true),
('dph-peh-extra-mcq-34','Pharmacy','Diploma in Pharmacy','mcq','free',1434,'{"question":"Which action supports safe self-medication?","translation":"सुरक्षित self-medication मा कुन कार्य सहयोगी हुन्छ?","options":["Use reliable advice and seek care for danger signs","Use another person''s prescription","Combine medicines without checking","Ignore package directions"],"correctIndex":0,"explanation":"Self-care should be informed, limited to suitable conditions and include referral for red flags.","explanationNe":"Self-medication विश्वसनीय सल्लाहमा आधारित हुनुपर्छ र खतराका संकेतमा referral गर्नुपर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-35','Pharmacy','Diploma in Pharmacy','mcq','free',1435,'{"question":"A medicine-use study finds frequent unnecessary antibiotics. What is a suitable response?","translation":"अनावश्यक antibiotic धेरै प्रयोग भएको अध्ययनले देखाएमा उपयुक्त कदम के हो?","options":["Education, guideline review and follow-up audit","Promote more antibiotic use","Delete the findings","Stop all medicines"],"correctIndex":0,"explanation":"Feedback, education and reassessment can improve prescribing and use.","explanationNe":"Feedback, शिक्षा र पुनः audit ले prescribing र प्रयोग सुधार्न सक्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-36','Pharmacy','Diploma in Pharmacy','mcq','free',1436,'{"question":"Which is a key purpose of environmental sanitation?","translation":"वातावरणीय सरसफाइको मुख्य उद्देश्य के हो?","options":["Reduce exposure to health hazards","Increase contamination","Avoid safe water","Mix hazardous waste"],"correctIndex":0,"explanation":"Sanitation reduces exposure to pathogens and environmental hazards.","explanationNe":"सरसफाइले रोगाणु र वातावरणीय जोखिमको सम्पर्क घटाउँछ।"}'::jsonb,true),
('dph-peh-extra-mcq-37','Pharmacy','Diploma in Pharmacy','mcq','free',1437,'{"question":"Which group is often more vulnerable to environmental health hazards?","translation":"वातावरणीय जोखिमबाट बढी प्रभावित हुन सक्ने समूह कुन हो?","options":["Young children and older adults","Only healthy adults","Only trained pharmacists","Only athletes"],"correctIndex":0,"explanation":"Vulnerability varies, but young children and older adults may face greater risks.","explanationNe":"सानो बालबालिका र वृद्धवृद्धा केही वातावरणीय जोखिमप्रति बढी संवेदनशील हुन सक्छन्।"}'::jsonb,true),
('dph-peh-extra-mcq-38','Pharmacy','Diploma in Pharmacy','mcq','free',1438,'{"question":"Which information is important in an ADR report?","translation":"ADR report मा कुन जानकारी महत्त्वपूर्ण हुन्छ?","options":["Suspected medicine, reaction and relevant patient/event details","Only pharmacy address","Only medicine price","Only reporter''s favourite brand"],"correctIndex":0,"explanation":"Reports should include available details on the suspected product, reaction, timing and patient, following the reporting form.","explanationNe":"रिपोर्टमा शंकास्पद औषधि, प्रतिक्रिया, समय र बिरामीसम्बन्धी उपलब्ध विवरण राख्नुपर्छ।"}'::jsonb,true),
('dph-peh-extra-mcq-39','Pharmacy','Diploma in Pharmacy','mcq','free',1439,'{"question":"Why is follow-up important after a medicine-use intervention?","translation":"औषधि प्रयोग सुधार कार्यक्रमपछि follow-up किन चाहिन्छ?","options":["To see whether practice improved","To avoid measuring results","To remove standards","To increase bias"],"correctIndex":0,"explanation":"Reassessment checks whether the intervention achieved improvement and whether further action is needed.","explanationNe":"पुनः मूल्याङ्कनले सुधार भयो कि भएन र थप कदम चाहिन्छ कि चाहिँदैन देखाउँछ।"}'::jsonb,true),
('dph-peh-extra-mcq-40','Pharmacy','Diploma in Pharmacy','mcq','free',1440,'{"question":"Which statement about observational studies is correct?","translation":"Observational study सम्बन्धी सही भनाइ कुन हो?","options":["They can identify associations but may be affected by bias and confounding","They always prove causation","They never use data","They always randomize treatment"],"correctIndex":0,"explanation":"Observational studies are valuable but causal interpretation requires careful assessment.","explanationNe":"Observational study उपयोगी हुन्छ तर कारणको निष्कर्ष सावधानीपूर्वक निकाल्नुपर्छ।"}'::jsonb,true),
('dph-peh-extra-mock-01','Pharmacy','Diploma in Pharmacy','mock','free',1401,'{"question":"Define pharmacoepidemiology and explain four applications.","answer":"It studies the use and effects of medicines in populations. Applications include describing medicine-use patterns, detecting safety signals, evaluating real-world outcomes and informing medicine policy.","answerNe":"यसले जनसमुदायमा औषधिको प्रयोग र प्रभाव अध्ययन गर्छ। उपयोगमा औषधि प्रयोगको ढाँचा, सुरक्षा संकेत, वास्तविक नतिजा मूल्याङ्कन र औषधि नीति समावेश हुन्छन्।"}'::jsonb,true),
('dph-peh-extra-mock-02','Pharmacy','Diploma in Pharmacy','mock','free',1402,'{"question":"Differentiate incidence and prevalence with an example.","answer":"Incidence counts new cases over a defined period; prevalence counts all existing cases at a specified time or period. For example, new cases diagnosed this year represent incidence, while everyone currently living with the disease represents prevalence.","answerNe":"Incidence ले निश्चित अवधिका नयाँ घटना गन्छ; prevalence ले निश्चित समयमा रहेका सबै घटना गन्छ। यस वर्ष नयाँ निदान भएका बिरामी incidence हुन् भने हाल रोग भएका सबै व्यक्ति prevalence हुन्।"}'::jsonb,true),
('dph-peh-extra-mock-03','Pharmacy','Diploma in Pharmacy','mock','free',1403,'{"question":"Compare cohort, case-control and cross-sectional study designs.","answer":"Cohort follows exposure groups over time; case-control selects by outcome and compares previous exposures; cross-sectional measures exposure and outcome at one point or short period.","answerNe":"Cohort ले exposure समूहलाई समयसँगै follow गर्छ; case-control ले outcome का आधारमा समूह छानी पहिलेको exposure तुलना गर्छ; cross-sectional ले एउटै समयमा exposure र outcome मापन गर्छ।"}'::jsonb,true),
('dph-peh-extra-mock-04','Pharmacy','Diploma in Pharmacy','mock','free',1404,'{"question":"What is confounding? Give a simple example.","answer":"Confounding occurs when a third factor is associated with both exposure and outcome and distorts their apparent relationship. For example, age may affect both medicine use and disease risk, complicating an observed association.","answerNe":"तेस्रो कारक exposure र outcome दुवैसँग सम्बन्धित भएर देखिएको सम्बन्ध बिगार्दा confounding हुन्छ। उदाहरण: उमेरले औषधि प्रयोग र रोग जोखिम दुवैमा असर गर्न सक्छ।"}'::jsonb,true),
('dph-peh-extra-mock-05','Pharmacy','Diploma in Pharmacy','mock','free',1405,'{"question":"Explain recall bias and one way to reduce it.","answer":"Recall bias occurs when participants remember past exposures differently. Use clear, standardized questions, records where available and similar data-collection methods for all groups.","answerNe":"सहभागीले विगतको exposure फरक तरिकाले सम्झँदा recall bias हुन्छ। स्पष्ट एउटै प्रकारका प्रश्न, उपलब्ध अभिलेख र सबै समूहमा समान data collection प्रयोग गरी घटाउन सकिन्छ।"}'::jsonb,true),
('dph-peh-extra-mock-06','Pharmacy','Diploma in Pharmacy','mock','free',1406,'{"question":"Define pharmacovigilance and outline the handling of a suspected ADR.","answer":"Pharmacovigilance detects, assesses, understands and prevents medicine-related harm. Record details, ensure patient care, inform the responsible clinician when appropriate and report through the current approved system.","answerNe":"Pharmacovigilance ले औषधिसम्बन्धी हानि पहिचान, मूल्याङ्कन र रोकथाम गर्छ। विवरण अभिलेख गर्ने, बिरामीको care सुनिश्चित गर्ने, आवश्यक clinician लाई जानकारी दिने र स्वीकृत प्रणालीबाट रिपोर्ट गर्ने।"}'::jsonb,true),
('dph-peh-extra-mock-07','Pharmacy','Diploma in Pharmacy','mock','free',1407,'{"question":"What is a medicine safety signal? Why does it need further assessment?","answer":"A signal is information suggesting a possible new or changed safety issue. It requires validation and assessment because reports or early observations may be incomplete and do not by themselves prove causation.","answerNe":"Safety signal सम्भावित नयाँ वा परिवर्तन भएको सुरक्षा समस्याको संकेत हो। प्रारम्भिक रिपोर्ट अपूर्ण हुन सक्छन् र कारण प्रमाणित गर्दैनन्, त्यसैले थप पुष्टि र मूल्याङ्कन चाहिन्छ।"}'::jsonb,true),
('dph-peh-extra-mock-08','Pharmacy','Diploma in Pharmacy','mock','free',1408,'{"question":"Describe drug utilization review and its steps.","answer":"DUR compares medicine use with predefined criteria. Steps: select medicine/problem, define standards, collect data, compare results, provide feedback, implement changes and repeat the review.","answerNe":"DUR ले औषधि प्रयोगलाई तोकिएको मापदण्डसँग तुलना गर्छ। चरण: औषधि/समस्या छनोट, मापदण्ड निर्धारण, data संकलन, तुलना, feedback, सुधार लागू र पुनः समीक्षा।"}'::jsonb,true),
('dph-peh-extra-mock-09','Pharmacy','Diploma in Pharmacy','mock','free',1409,'{"question":"Explain antimicrobial stewardship and give four activities.","answer":"It promotes appropriate antimicrobial use to improve outcomes and limit resistance. Activities include following guidelines, selecting appropriate drug/dose/route/duration, reviewing therapy and educating patients not to share or misuse antibiotics.","answerNe":"यसले नतिजा सुधार र resistance घटाउन antimicrobial को उचित प्रयोग प्रोत्साहन गर्छ। Guideline पालना, सही औषधि/dose/route/duration, उपचार समीक्षा र antibiotic बाँडेर/दुरुपयोग नगर्न शिक्षा यसका गतिविधि हुन्।"}'::jsonb,true),
('dph-peh-extra-mock-10','Pharmacy','Diploma in Pharmacy','mock','free',1410,'{"question":"Differentiate primary, secondary and tertiary prevention with examples.","answer":"Primary prevents disease (e.g. immunization); secondary detects disease early (e.g. screening); tertiary reduces complications or disability (e.g. rehabilitation).","answerNe":"Primary ले रोग रोक्छ (खोप); secondary ले चाँडै पत्ता लगाउँछ (screening); tertiary ले जटिलता वा अशक्तता घटाउँछ (rehabilitation)।"}'::jsonb,true),
('dph-peh-extra-mock-11','Pharmacy','Diploma in Pharmacy','mock','free',1411,'{"question":"Define disease surveillance and list its main stages.","answer":"Surveillance is systematic collection, analysis, interpretation and sharing of health data for public-health action. It includes data collection, analysis, interpretation, dissemination and response.","answerNe":"Disease surveillance जनस्वास्थ्य कार्यका लागि स्वास्थ्य तथ्यांकको व्यवस्थित संकलन, विश्लेषण, व्याख्या र साझा गर्ने प्रक्रिया हो।"}'::jsonb,true),
('dph-peh-extra-mock-12','Pharmacy','Diploma in Pharmacy','mock','free',1412,'{"question":"Explain the importance of safe water and sanitation in public health.","answer":"Safe water and sanitation prevent waterborne and sanitation-related infections, protect dignity and support healthy communities. Monitoring, hygiene education and safe waste disposal are important measures.","answerNe":"सुरक्षित पानी र सरसफाइले पानी तथा सरसफाइबाट सर्ने संक्रमण रोक्छ, मर्यादा जोगाउँछ र स्वस्थ समुदाय बनाउँछ। अनुगमन, स्वच्छता शिक्षा र सुरक्षित फोहोर व्यवस्थापन महत्त्वपूर्ण छन्।"}'::jsonb,true),
('dph-peh-extra-mock-13','Pharmacy','Diploma in Pharmacy','mock','free',1413,'{"question":"Describe healthcare-waste segregation and sharps safety.","answer":"Segregate waste at source using approved labeled containers. Place needles and other sharps in puncture-resistant containers; do not recap used needles unless a specific approved procedure requires it, and follow facility protocols.","answerNe":"स्वीकृत label भएका container प्रयोग गरी फोहोर उत्पादन भएको स्थानमै छुट्याउनुपर्छ। सुई र धारिला वस्तु puncture-resistant container मा राख्ने, विशेष स्वीकृत प्रक्रिया नभएसम्म प्रयोग भएको सुई पुनः cap नगर्ने र संस्थाको protocol पालना गर्ने।"}'::jsonb,true),
('dph-peh-extra-mock-14','Pharmacy','Diploma in Pharmacy','mock','free',1414,'{"question":"What are the main types of environmental health hazards? Give examples.","answer":"Physical hazards include noise and radiation; chemical hazards include pesticides and toxic substances; biological hazards include pathogens; social and built-environment factors include overcrowding and unsafe housing.","answerNe":"Physical जोखिममा noise/radiation, chemical मा pesticide/toxic पदार्थ, biological मा रोगाणु र सामाजिक/निर्मित वातावरणमा भीडभाड तथा असुरक्षित आवास पर्छन्।"}'::jsonb,true),
('dph-peh-extra-mock-15','Pharmacy','Diploma in Pharmacy','mock','free',1415,'{"question":"Explain relative risk and odds ratio in simple terms.","answer":"Relative risk compares the probability of an outcome in exposed and unexposed groups. Odds ratio compares the odds of exposure or outcome between groups and is commonly used in case-control studies.","answerNe":"Relative risk ले exposure भएको र नभएको समूहको outcome जोखिम तुलना गर्छ। Odds ratio ले समूहबीच odds तुलना गर्छ र case-control study मा धेरै प्रयोग हुन्छ।"}'::jsonb,true),
('dph-peh-extra-mock-16','Pharmacy','Diploma in Pharmacy','mock','free',1416,'{"question":"Why do observational studies not always prove causation?","answer":"They may be affected by confounding, selection bias, information bias, measurement error and reverse causation. Causal conclusions require careful design, analysis and supporting evidence.","answerNe":"Observational study मा confounding, selection bias, information bias, measurement error र reverse causation हुन सक्छ। कारणको निष्कर्षका लागि राम्रो design, analysis र थप प्रमाण चाहिन्छ।"}'::jsonb,true),
('dph-peh-extra-mock-17','Pharmacy','Diploma in Pharmacy','mock','free',1417,'{"question":"List key elements of a useful adverse drug reaction report.","answer":"Include identifiable patient information as permitted, suspected medicine, description of reaction, onset and outcome, relevant medical history and reporter details, following the official reporting form and privacy rules.","answerNe":"आधिकारिक फाराम र गोपनीयता नियमअनुसार अनुमति भएको बिरामी विवरण, शंकास्पद औषधि, प्रतिक्रियाको विवरण, सुरु भएको समय/नतिजा, सम्बन्धित इतिहास र reporter विवरण राख्नुपर्छ।"}'::jsonb,true),
('dph-peh-extra-mock-18','Pharmacy','Diploma in Pharmacy','mock','free',1418,'{"question":"How can a community pharmacy support public health?","answer":"It can provide reliable medicine information, adherence counselling, health education, antimicrobial stewardship, authorized public-health services and timely referral while protecting confidentiality.","answerNe":"Community pharmacy ले सही औषधि जानकारी, नियमित प्रयोग परामर्श, स्वास्थ्य शिक्षा, antimicrobial stewardship, अनुमति प्राप्त जनस्वास्थ्य सेवा र समयमै referral दिन सक्छ।"}'::jsonb,true),
('dph-peh-extra-mock-19','Pharmacy','Diploma in Pharmacy','mock','free',1419,'{"question":"A review shows frequent inappropriate antibiotic prescriptions. Propose an improvement plan.","answer":"Confirm the finding, discuss guidelines with prescribers, provide education, review patient counselling and dispensing practices, monitor antibiotic indicators and repeat the audit to assess change.","answerNe":"नतिजा पुष्टि गर्ने, prescriber सँग guideline छलफल, शिक्षा दिने, counselling/dispensing अभ्यास समीक्षा, antibiotic सूचक अनुगमन र परिवर्तन मूल्याङ्कन गर्न पुनः audit गर्ने।"}'::jsonb,true),
('dph-peh-extra-mock-20','Pharmacy','Diploma in Pharmacy','mock','free',1420,'{"question":"Explain why confidentiality matters in public-health and medicine-safety reporting.","answer":"Confidentiality protects patient dignity and trust. Share only the minimum necessary information through authorized channels, follow applicable law and use secure records while enabling public-health action.","answerNe":"गोपनीयताले बिरामीको मर्यादा र विश्वास जोगाउँछ। आवश्यक न्यूनतम सूचना मात्र स्वीकृत माध्यमबाट साझा गर्ने, कानुन पालना गर्ने र सुरक्षित अभिलेख राख्दै जनस्वास्थ्य कार्यमा सहयोग गर्ने।"}'::jsonb,true)
